import{_ as a,o as s,c as e,ag as n}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"SetRtWarning 输出警告信息","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetRtWarning.md","filePath":"3. 指令/5. 设置指令/SetRtWarning.md","lastUpdated":1778862643000}'),i={name:"3. 指令/5. 设置指令/SetRtWarning.md"};function l(r,t,d,o,h,g){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="setrtwarning-输出警告信息" tabindex="-1">SetRtWarning 输出警告信息 <a class="header-anchor" href="#setrtwarning-输出警告信息" aria-label="Permalink to &quot;SetRtWarning 输出警告信息&quot;">​</a></h1><p>该指令用于<strong>在系统中触发一个警告级别的信息，但不会中断机器人的当前动作或程序运行</strong>。它的严重程度介于&quot;提示 (Info)&quot;与&quot;错误 (Err)&quot;之间，通常用于提醒操作人员存在潜在风险或需要注意的非致命异常。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetRtWarning(msg, errId) SetRtWarning(警告信息, 警告编号)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>msg：警告信息（errInfo）</td><td>str / STRING 变量</td><td>显示在示教器或日志中的警告文字。例如：&quot;润滑油位偏低&quot;、&quot;电池电量不足&quot;或&quot;检测到节拍轻微偏移&quot;。</td><td></td></tr><tr><td>errId：警告编号（errId）</td><td>int / INT 变量</td><td>系统分配的警告 ID。</td><td>取值范围：<strong>80001 - 90000</strong>（此范围专门预留给用户自定义的警告信息）。</td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>当 <code>SetRtWarning</code> 被触发时：</p><ol><li><strong>不停机</strong>：机器人继续执行当前的运动指令。</li><li><strong>状态显示</strong>：示教器的状态栏通常会变为黄色（或显示警告图标），并弹出对应的文字提示。</li><li><strong>日志记录</strong>：警告会被永久记录在系统的历史记录中，供后续设备维护人员查看。</li></ol><hr><h2 id="示例-预防性维护逻辑" tabindex="-1">示例：预防性维护逻辑 <a class="header-anchor" href="#示例-预防性维护逻辑" aria-label="Permalink to &quot;示例：预防性维护逻辑&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 假设变量 R1 记录了夹爪的使用次数</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (R1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">THEN</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    SetRtWarning</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;警告：夹爪密封件已达使用寿命，请安排检查&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80005</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ENDIF</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>执行结果：</strong></p><p>机器人继续正常抓取和放置工件，但操作员会在屏幕上看到 <strong>80005</strong> 号警告，提示其在下次停机维护时更换零件，而不至于因为突然损坏导致生产线意外停摆。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>预防性维护</strong>：根据运行时间或循环次数提醒更换易损件（吸嘴、焊条、滤网等）。</li><li><strong>非关键传感器异常</strong>：例如辅助检测传感器未检测到零件，但程序可以通过备选方案继续运行时，发出警告。</li><li><strong>环境监控</strong>：控制柜温度过高或气压接近临界下限时的预警。</li><li><strong>节拍超限</strong>：当实际生产节拍比设定值慢时，发出警告提示进行人工排查。</li></ul><hr><h3 id="埃斯顿-rcs2-系统三类消息对比表" tabindex="-1"><strong>埃斯顿 RCS2 系统三类消息对比表</strong> <a class="header-anchor" href="#埃斯顿-rcs2-系统三类消息对比表" aria-label="Permalink to &quot;**埃斯顿 RCS2 系统三类消息对比表**&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">指令</th><th style="text-align:left;">编号范围</th><th style="text-align:left;">机器人状态</th><th style="text-align:left;">严重程度</th><th style="text-align:left;">用途</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SetRtInfo</strong></td><td style="text-align:left;">70001-80000</td><td style="text-align:left;"><strong>持续运行</strong></td><td style="text-align:left;">低 (绿/蓝)</td><td style="text-align:left;">流程记录、计数、状态显示</td></tr><tr><td style="text-align:left;"><strong>SetRtWarning</strong></td><td style="text-align:left;">80001-90000</td><td style="text-align:left;"><strong>持续运行</strong></td><td style="text-align:left;">中 (黄)</td><td style="text-align:left;">潜在风险预警、维护提醒</td></tr><tr><td style="text-align:left;"><strong>SetRtToErr</strong></td><td style="text-align:left;">90001-100000</td><td style="text-align:left;"><strong>强制停机</strong></td><td style="text-align:left;">高 (红)</td><td style="text-align:left;">致命错误、安全保护、停工处理</td></tr></tbody></table>`,22)])])}const c=a(i,[["render",l]]);export{k as __pageData,c as default};
